from .uc_data_transfer_base import UcDataTransferBase


class UcIcmp(UcDataTransferBase):

    def __init__(self, name, dt_definition, configuration, uc_connection, logger_name='ute_ue', test_name=None):
        """
        Init

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param uc_connection:
        :param logger_name:
        :param test_name:
        """
        super(UcIcmp, self).__init__(name, dt_definition, configuration, uc_connection, logger_name, test_name)

    def start(self):
        """
        Start data transfer
        :return:
        """
        try:
            if not self.existing_uc_test:
                self._create_new_test()
            self._start_and_wait_for_complete()
        finally:
            if not self.existing_uc_test:
                self._delete_test()

    def _create_new_test(self):
        self._validate_protocol_details(self._dt_definition.protocol_details)
        params = self._get_params_from_dt_definition(self._dt_definition)
        params = self._check_parameters(params)
        self._uc_connection.new_test(name=self.test_name, test_type='ICMP ping', test_params=params)
        self.logger.debug('Created new test {} type ICMP with params {}'.format(self.test_name, params))

    @staticmethod
    def _get_params_from_dt_definition(dt_definition):
        details = dt_definition.protocol_details
        params = {'address': details.get('address'),
                  'packetCount': details.get('packetCount', 0),
                  'packetSize': details.get('packetSize', 16),
                  'interval': details.get('interval', 0),
                  'detailedResults': True}
        if not dt_definition.is_forever_duration() \
                and details.get('duration') != '0s' \
                and details.get('duration') != '0 seconds':
            params['duration'] = int(dt_definition.duration)
        return params

    @staticmethod
    def _validate_protocol_details(details):
        if not details.get('address'):
            raise ValueError('Mandatory parameter missing: address')

    @staticmethod
    def _check_parameters(parameters):
        if parameters['packetCount'] == 0 and not parameters.get('duration', 0) == 0:
            parameters['packetCount'] = 10
        elif parameters['packetCount'] == 0 and parameters.get('duration', 0) == 0:
            parameters['packetCount'] = 100
        return parameters
